script_dir=fileparts(mfilename('fullpath'));root_dir=fileparts(script_dir);w=fullfile(root_dir,'waveforms','06-open-loop-angle');a=fullfile(root_dir,'assets','06-open-loop-angle');if ~exist(a,'dir');mkdir(a);end
